INSERT INTO DimCustomer (SK_CustomerID, CustomerID, TaxID, Status, LastName, FirstName, MiddleInitial, Gender, Tier, DOB, AddressLine1, AddressLine2, PostalCode, City, StateProv, Country, Phone1, Phone2, Phone3, Email1, Email2, NationalTaxRateDesc, NationalTaxRate, LocalTaxRateDesc, LocalTaxRate, AgencyID, CreditRating, NetWorth, MarketingNameplate, IsCurrent, BatchID, EffectiveDate, EndDate) WITH Customers_Preproc AS (SELECT CXML.C_ID AS CustomerID, TRIM(CXML.C_TAX_ID) AS TaxID, CXML.C_GNDR AS GenderRaw, TRY_CAST(CXML.C_TIER AS INT) AS Tier, TRY_CAST(CXML.C_DOB AS DATE) AS DOB, TRIM(CCIN.C_PRIM_EMAIL) AS Email1, TRIM(CCIN.C_ALT_EMAIL) AS Email2, TRIM(NXML.C_F_NAME) AS FirstName, TRIM(NXML.C_M_NAME) AS MiddleInitial, TRIM(NXML.C_L_NAME) AS LastName, TRIM(ADXML.C_ADLINE1) AS AddressLine1, TRIM(ADXML.C_ADLINE2) AS AddressLine2, TRIM(ADXML.C_ZIPCODE) AS PostalCode, TRIM(ADXML.C_CITY) AS City, TRIM(ADXML.C_STATE_PROV) AS StateProv, TRIM(ADXML.C_CTRY) AS Country, CASE WHEN NOT CP1XML.C_CTRY_CODE IS NULL AND NOT CP1XML.C_AREA_CODE IS NULL AND NOT CP1XML.C_LOCAL IS NULL THEN '+' || CP1XML.C_CTRY_CODE || ' (' || CP1XML.C_AREA_CODE || ') ' || CP1XML.C_LOCAL WHEN CP1XML.C_CTRY_CODE IS NULL AND (NOT CP1XML.C_AREA_CODE IS NULL AND NOT CP1XML.C_LOCAL IS NULL) THEN '(' || CP1XML.C_AREA_CODE || ') ' || CP1XML.C_LOCAL WHEN (CP1XML.C_CTRY_CODE IS NULL AND CP1XML.C_AREA_CODE IS NULL) AND NOT CP1XML.C_LOCAL IS NULL THEN CP1XML.C_LOCAL END AS Phone1_V1, CASE WHEN NOT CP2XML.C_CTRY_CODE IS NULL AND NOT CP2XML.C_AREA_CODE IS NULL AND NOT CP2XML.C_LOCAL IS NULL THEN '+' || CP2XML.C_CTRY_CODE || ' (' || CP2XML.C_AREA_CODE || ') ' || CP2XML.C_LOCAL WHEN CP2XML.C_CTRY_CODE IS NULL AND (NOT CP2XML.C_AREA_CODE IS NULL AND NOT CP2XML.C_LOCAL IS NULL) THEN '(' || CP2XML.C_AREA_CODE || ') ' || CP2XML.C_LOCAL WHEN (CP2XML.C_CTRY_CODE IS NULL AND CP2XML.C_AREA_CODE IS NULL) AND NOT CP2XML.C_LOCAL IS NULL THEN CP2XML.C_LOCAL END AS Phone2_V1, CASE WHEN NOT CP3XML.C_CTRY_CODE IS NULL AND NOT CP3XML.C_AREA_CODE IS NULL AND NOT CP3XML.C_LOCAL IS NULL THEN '+' || CP3XML.C_CTRY_CODE || ' (' || CP3XML.C_AREA_CODE || ') ' || CP3XML.C_LOCAL WHEN CP3XML.C_CTRY_CODE IS NULL AND (NOT CP3XML.C_AREA_CODE IS NULL AND NOT CP3XML.C_LOCAL IS NULL) THEN '(' || CP3XML.C_AREA_CODE || ') ' || CP3XML.C_LOCAL WHEN (CP3XML.C_CTRY_CODE IS NULL AND CP3XML.C_AREA_CODE IS NULL) AND NOT CP3XML.C_LOCAL IS NULL THEN CP3XML.C_LOCAL END AS Phone3_V1, TRIM(TR.TX_NAME) AS NationalTaxRateDesc, TR.TX_RATE AS NationalTaxRate, TRIM(TR2.TX_NAME) AS LocalTaxRateDesc, TR2.TX_RATE AS LocalTaxRate, CP1XML.C_EXT AS C_EXT1, CP2XML.C_EXT AS C_EXT2, CP3XML.C_EXT AS C_EXT3, AXML.ActionType, TRY_CAST(AXML.ActionTS AS TIMESTAMP) AS ActionTS, TRY_CAST(AXML.Action_Id AS BIGINT) AS ActionSeq FROM Source.CustomerXML AS CXML INNER JOIN Source.ActionXML AS AXML ON CXML.Action_Id = AXML.Action_Id LEFT JOIN Source.NameXML AS NXML ON CXML.Customer_Id = NXML.Customer_Id LEFT JOIN Source.ContactInfoXML AS CCIN ON CXML.Customer_Id = CCIN.Customer_Id LEFT JOIN Source.AddressXML AS ADXML ON CXML.Customer_Id = ADXML.Customer_Id LEFT JOIN Source.TaxInfoXML AS TXML ON CXML.Customer_Id = TXML.Customer_Id LEFT JOIN Source.TaxRate AS TR ON TXML.C_NAT_TX_ID = TR.TX_ID LEFT JOIN Source.TaxRate AS TR2 ON TXML.C_LCL_TX_ID = TR2.TX_ID LEFT JOIN Source.C_PHONE_1_XML AS CP1XML ON CCIN.ContactInfo_Id = CP1XML.ContactInfo_Id LEFT JOIN Source.C_PHONE_2_XML AS CP2XML ON CCIN.ContactInfo_Id = CP2XML.ContactInfo_Id LEFT JOIN Source.C_PHONE_3_XML AS CP3XML ON CCIN.ContactInfo_Id = CP3XML.ContactInfo_Id WHERE AXML.ActionType IN ('NEW', 'UPDCUST', 'INACT')), CustomerEvents AS (SELECT *, CASE WHEN NOT C_EXT1 IS NULL THEN Phone1_V1 || C_EXT1 ELSE Phone1_V1 END AS Phone1, CASE WHEN NOT C_EXT2 IS NULL THEN Phone2_V1 || C_EXT2 ELSE Phone2_V1 END AS Phone2, CASE WHEN NOT C_EXT3 IS NULL THEN Phone3_V1 || C_EXT3 ELSE Phone3_V1 END AS Phone3 FROM Customers_Preproc), CustomersFilled AS (SELECT CustomerID, ActionTS, ActionSeq, ActionType, LAST_VALUE(TaxID IGNORE NULLS) OVER w AS TaxID, LAST_VALUE(GenderRaw IGNORE NULLS) OVER w AS GenderRaw, LAST_VALUE(Tier IGNORE NULLS) OVER w AS Tier, LAST_VALUE(DOB IGNORE NULLS) OVER w AS DOB, LAST_VALUE(Email1 IGNORE NULLS) OVER w AS Email1, LAST_VALUE(Email2 IGNORE NULLS) OVER w AS Email2, LAST_VALUE(FirstName IGNORE NULLS) OVER w AS FirstName, LAST_VALUE(MiddleInitial IGNORE NULLS) OVER w AS MiddleInitial, LAST_VALUE(LastName IGNORE NULLS) OVER w AS LastName, LAST_VALUE(AddressLine1 IGNORE NULLS) OVER w AS AddressLine1, LAST_VALUE(AddressLine2 IGNORE NULLS) OVER w AS AddressLine2, LAST_VALUE(PostalCode IGNORE NULLS) OVER w AS PostalCode, LAST_VALUE(City IGNORE NULLS) OVER w AS City, LAST_VALUE(StateProv IGNORE NULLS) OVER w AS StateProv, LAST_VALUE(Country IGNORE NULLS) OVER w AS Country, LAST_VALUE(Phone1 IGNORE NULLS) OVER w AS Phone1, LAST_VALUE(Phone2 IGNORE NULLS) OVER w AS Phone2, LAST_VALUE(Phone3 IGNORE NULLS) OVER w AS Phone3, LAST_VALUE(NationalTaxRateDesc IGNORE NULLS) OVER w AS NationalTaxRateDesc, LAST_VALUE(NationalTaxRate IGNORE NULLS) OVER w AS NationalTaxRate, LAST_VALUE(LocalTaxRateDesc IGNORE NULLS) OVER w AS LocalTaxRateDesc, LAST_VALUE(LocalTaxRate IGNORE NULLS) OVER w AS LocalTaxRate, MAX(CASE WHEN ActionType = 'INACT' THEN 1 ELSE 0 END) OVER w AS WasInactivated FROM CustomerEvents WINDOW w AS (PARTITION BY CustomerID ORDER BY ActionTS, ActionSeq ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), CustomersDaily AS (SELECT * FROM CustomersFilled QUALIFY ROW_NUMBER() OVER (PARTITION BY CustomerID, CAST(ActionTS AS DATE) ORDER BY ActionTS DESC, ActionSeq DESC) = 1), CustomerVersions AS (SELECT *, CAST(ActionTS AS DATE) AS EffectiveDate, COALESCE(LEAD(CAST(ActionTS AS DATE)) OVER (PARTITION BY CustomerID ORDER BY ActionTS ASC), CAST('9999-12-31' AS DATE)) AS EndDate, (LEAD(ActionTS) OVER (PARTITION BY CustomerID ORDER BY ActionTS ASC) IS NULL) AS IsLatest FROM CustomersDaily) SELECT ROW_NUMBER() OVER (ORDER BY V.CustomerID, V.EffectiveDate) AS SK_CustomerID, V.CustomerID, V.TaxID, CASE WHEN V.WasInactivated = 1 THEN 'Inactive' ELSE 'Active' END AS Status, V.LastName, V.FirstName, V.MiddleInitial, CASE WHEN UPPER(TRIM(V.GenderRaw)) IN ('M', 'F') THEN UPPER(TRIM(V.GenderRaw)) ELSE 'U' END AS Gender, V.Tier, V.DOB, V.AddressLine1, V.AddressLine2, V.PostalCode, V.City, V.StateProv, V.Country, V.Phone1, V.Phone2, V.Phone3, V.Email1, V.Email2, V.NationalTaxRateDesc, V.NationalTaxRate, V.LocalTaxRateDesc, V.LocalTaxRate, TRIM(P.AgencyID) AS AgencyID, P.CreditRating AS CreditRating, P.NetWorth AS NetWorth, CASE WHEN P.AgencyID IS NULL THEN NULL ELSE NULLIF(CONCAT_WS('+', CASE WHEN P.NetWorth > 1000000 OR P.Income > 200000 THEN 'HighValue' END, CASE WHEN P.NumberChildren > 3 OR P.NumberCreditCards > 5 THEN 'Expenses' END, CASE WHEN P.Age > 45 THEN 'Boomer' END, CASE WHEN P.Income < 50000 OR P.CreditRating < 600 OR P.NetWorth < 100000 THEN 'MoneyAlert' END, CASE WHEN P.NumberCars > 3 OR P.NumberCreditCards > 7 THEN 'Spender' END, CASE WHEN P.Age < 25 AND P.NetWorth > 1000000 THEN 'Inherited' END), '') END AS MarketingNameplate, V.IsLatest AS IsCurrent, 1 AS BatchID, V.EffectiveDate, V.EndDate FROM CustomerVersions AS V LEFT JOIN Source.Prospect AS P ON V.IsLatest AND UPPER(V.FirstName) = UPPER(TRIM(P.FirstName)) AND UPPER(V.LastName) = UPPER(TRIM(P.LastName)) AND UPPER(V.AddressLine1) = UPPER(TRIM(P.AddressLine1)) AND UPPER(COALESCE(V.AddressLine2, '')) = UPPER(COALESCE(TRIM(P.AddressLine2), '')) AND UPPER(V.PostalCode) = UPPER(TRIM(P.PostalCode)) ORDER BY V.CustomerID, V.EffectiveDate